def write_csv(path: Path, rows: list[dict]) -> None:
    with path.open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0]), quoting=csv.QUOTE_MINIMAL, lineterminator="\n")
        w.writeheader()
        w.writerows(rows)


def main() -> None:
    write_csv(A / "DEM_CHRONOLOGY_AUDIT.csv", DEM)
    write_csv(A / "INVENTORY_PROVENANCE_AUDIT.csv", INV)
    keys = ["risk_id", "issue", "leakage_category", "severity", "landscapes_affected", "evidence",
            "potential_influence_on_pr_lift", "affects", "targeted_follow_up_needed", "recommended_action"]
    write_csv(A / "LEAKAGE_RISK_REGISTER.csv", [dict(zip(keys, r)) for r in RISK])


if __name__ == "__main__":
    main()
